100	// validatePlanDate 解析 YYYY-MM-DD 真实日期，且不得早于本机今天。
101	func (l *Ledger) validatePlanDate(raw, field string) (string, error) {
102		_, text, err := parseFiniteDate(raw, field)
103		if err != nil {
104			return "", err
105		}
106		todayText := l.now().Format(DateLayout)
107		if text < todayText {
108			return "", validationError("%s %s 不能早于本机今天 %s", field, text, todayText)
109		}
110		return text, nil
111	}
112	
113	// CreatePlan 为已登记器具建立一项校准计划。计划编号全台账唯一（即使对应
114	// 已结束计划也不能复用），计划日期须真实存在且不早于本机今天，说明非空；
115	// 每件器具最多有一项未完成、未取消的计划。任一条件不满足都明确拒绝，
116	// 不新增或改动任何记录。
117	//
118	// 返回的计划只是已保存内容的展示副本，与台账内存储不共享内存：调用方为
119	// 显示而改动编号、日期、状态或关联证书，不占用或释放正式计划编号，不影响
120	// 每件器具最多一项未结束计划的判断，也不会在此后正常写盘时被带入台账文件；
121	// 重新查询同一台账得到的仍是最后成功保存的计划。
122	func (l *Ledger) CreatePlan(in PlanInput) (*Plan, error) {
123		number, err := cleanText(in.Number)
124		if err != nil {
125			return nil, fmt.Errorf("计划编号无效：%w", err)
126		}
127		instID, err := cleanText(in.InstrumentID)
128		if err != nil {
129			return nil, fmt.Errorf("器具编号无效：%w", err)
130		}
131		note, err := cleanText(in.Note)
132		if err != nil {
133			return nil, fmt.Errorf("计划说明无效：%w", err)
134		}
135		if l.findInstrument(instID) == nil {
136			return nil, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
137		}
138		dateText, err := l.validatePlanDate(in.Date, "计划日期")
139		if err != nil {
140			return nil, err
141		}
142		if l.findPlan(number) != nil {
143			return nil, validationError("计划编号 %s 已存在，编号必须全台账唯一且不能复用", number)
144		}
145		for i := range l.data.Plans {
146			p := &l.data.Plans[i]
147			if p.InstrumentID == instID && p.Open() {
148				return nil, validationError(
149					"器具 %s 已有未结束的计划 %s（计划日期 %s），每件器具最多一项未结束计划",
150					instID, p.Number, p.PlannedDate)
151			}
152		}
153		p := Plan{
154			Number:       number,
155			InstrumentID: instID,
156			PlannedDate:  dateText,
157			OriginalDate: dateText,
158			Note:         note,
159			CreatedAt:    l.now().Format(time.RFC3339),
160			Status:       PlanStatusOpen,
161		}
162		l.data.Plans = append(l.data.Plans, p)
163		if err := l.save(); err != nil {
164			return nil, err
165		}
166		return clonePlanPtr(l.findPlan(number)), nil
167	}
168	
169	// requireOpenPlan 找到计划并确认其尚未结束；已结束计划返回明确的校验错误。
170	func (l *Ledger) requireOpenPlan(number string) (*Plan, error) {
171		p := l.findPlan(number)
172		if p == nil {
173			return nil, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
174		}
175		if !p.Open() {
176			return nil, validationError("计划 %s %s，已结束的计划不能再改期、取消或重新开启",
177				number, p.Status)
178		}
179		return p, nil
180	}
181	
182	// ReschedulePlan 改期一项未结束的计划。原因必须非空，新日期必须真实存在且
183	// 不早于操作当天；每次改期保留修改前后的日期、操作时间和原因。
184	// 找不到计划或计划已结束时拒绝且不改动记录。
185	//
186	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
187	// 台账（含同一对象随后的核对、计划查询与待办）与改期前完全一致——当前计划
188	// 日期不改变，失败申请的原因和时间既不进入改期历史、不改变待办标记，也不会
189	// 在此后其他成功操作写盘时被顺带写入；恢复可写后重新提交才按当时时间生效，
190	// 且只新增一条从最后成功保存的日期到新日期的记录。
191	//
192	// 返回的计划（含改期历史）是已保存内容的独立展示副本：调用方改动其中的
193	// 当前日期、状态或任意一条改期记录的原因、前后日期、操作时间，调换、删去
194	// 或追加列表记录，都只影响自己手中的那一份，不改写正式计划，也不影响
195	// 此前分别取得的操作结果、计划查询结果和核对结果。
196	func (l *Ledger) ReschedulePlan(number, newDate, reason string) (*Plan, error) {
197		number, err := cleanText(number)
198		if err != nil {
199			return nil, fmt.Errorf("计划编号无效：%w", err)
200		}
201		reason, err = cleanText(reason)
202		if err != nil {
203			return nil, fmt.Errorf("改期原因无效：%w", err)
204		}
205		dateText, err := l.validatePlanDate(newDate, "新计划日期")
206		if err != nil {
207			return nil, err
208		}
209		p, err := l.requireOpenPlan(number)
210		if err != nil {
211			return nil, err
212		}
213		// 即使新日期与当前日期相同也照常记录：保留修改前后的日期、操作时间和原因。
214		change := PlanChange{
215			From:      p.PlannedDate,
216			To:        dateText,
217			ChangedAt: l.now().Format(time.RFC3339),
218			Reason:    reason,
219		}
220		// 在整份计划切片的独立副本上暂存改期：只有原子替换台账文件成功后才提交。
221		// 写盘失败时恢复原切片（含原计划日期与改期历史），保证同一台账对象随后看到的
222		// 计划日期、改期历史与待办标记都与改期前一致，且不会被之后的写盘顺带写入。
223		original := l.data.Plans
224		staged := make([]Plan, len(original))
225		copy(staged, original)
226		for i := range staged {
227			if staged[i].Number != number {
228				continue
229			}
230			staged[i].Changes = append(append([]PlanChange(nil), staged[i].Changes...), change)
231			staged[i].PlannedDate = dateText
232		}
233		l.data.Plans = staged
234		if err := l.save(); err != nil {
235			l.data.Plans = original
236			return nil, err
237		}
238		return clonePlanPtr(l.findPlan(number)), nil
239	}
240	
241	// CancelPlan 取消一项未结束的计划，原因必须非空。取消后保留原计划、取消时间
242	// 和原因，不再列入待办，也不能重新开启。找不到计划或计划已结束时拒绝。
243	//
244	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
245	// 台账（含同一对象随后的计划查询、按器具核对与待办）与取消前完全一致——
246	// 计划仍为未完成并继续列入待办，取消时间和原因不留下本次申请的内容，也不会
247	// 在此后其他成功操作写盘时被顺带写入；文件仍不可写时再次提交仍报保存错误
248	// （不会被当成“已结束”拒绝），恢复可写后无需重新打开台账，重新提交才真正
249	// 取消，取消时间和原因取本次成功提交而非失败那次。
250	//
251	// 返回的取消结果是独立展示副本：调用方把状态改回未完成或清空取消信息，
252	// 只影响自己那一份，正式计划仍保持已取消且不再列入待办。
253	func (l *Ledger) CancelPlan(number, reason string) (*Plan, error) {
254		number, err := cleanText(number)
255		if err != nil {
256			return nil, fmt.Errorf("计划编号无效：%w", err)
257		}
258		reason, err = cleanText(reason)
259		if err != nil {
260			return nil, fmt.Errorf("取消原因无效：%w", err)
261		}
262		if _, err := l.requireOpenPlan(number); err != nil {
263			return nil, err
264		}
265		canceledAt := l.now().Format(time.RFC3339)
266		// 在整份计划切片的独立副本上暂存取消：只有原子替换台账文件成功后才提交。
267		// 写盘失败时恢复原切片（计划仍为未完成、取消时间与原因为空），保证同一
268		// 台账对象随后看到的计划状态、待办与核对都与取消前一致，再次提交不会被
269		// 当成“已结束”，失败信息也不会被之后的写盘顺带写入。
270		original := l.data.Plans
271		staged := make([]Plan, len(original))
272		copy(staged, original)
273		for i := range staged {
274			if staged[i].Number != number {
275				continue
276			}
277			staged[i].Status = PlanStatusCanceled
278			staged[i].CanceledAt = canceledAt
279			staged[i].CancelReason = reason
280		}
281		l.data.Plans = staged
282		if err := l.save(); err != nil {
283			l.data.Plans = original
284			return nil, err
285		}
286		return clonePlanPtr(l.findPlan(number)), nil
287	}
288	
289	// CompletePlan 用一张台账中已有的证书完成计划。证书必须属于该器具，校准日期
290	// 不得早于计划最初建立的本机日期，且未被用于完成其他计划。符合条件后保存
291	// 完成时间和证书编号；超差证书同样表示校准工作已完成。
292	//
293	// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
294	// 台账（含同一对象随后的计划查询、按器具核对与待办）与完成前完全一致——
295	// 计划仍为未完成并继续列入待办，完成时间与关联证书编号保持操作前的值，
296	// 计划日期、已有改期记录和待办日期标记都不改变，该证书也不会被算作已用于
297	// 完成计划（既不会被随后的提交当成“此前已完成”跳过保存，也不会被其他成功
298	// 写盘顺带写入文件）；恢复可写后无需重新打开台账，重新提交才真正完成，
299	// 完成时间取本次成功操作而非失败时刻。
300	//
301	// 再次用同一证书完成同一已保存为完成的计划返回原结果，不增加记录或刷新
302	// 完成时间；已完成计划改用另一证书、证书不存在或不符合条件、完成已取消
303	// 计划均拒绝。
304	//
305	// 返回的完成结果（含再次完成返回的原结果）是独立展示副本：调用方把它改成
306	// 未完成或换掉证书编号，正式计划仍保持完成，原证书仍算已用于该计划，不能
307	// 因此拿去完成另一项计划，完成时间也不会被刷新。
308	func (l *Ledger) CompletePlan(number, certificateNumber string) (*Plan, bool, error) {
309		number, err := cleanText(number)
310		if err != nil {
311			return nil, false, fmt.Errorf("计划编号无效：%w", err)
312		}
313		certificateNumber, err = cleanText(certificateNumber)
314		if err != nil {
315			return nil, false, fmt.Errorf("证书编号无效：%w", err)
316		}
317		p := l.findPlan(number)
318		if p == nil {
319			return nil, false, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
320		}
321		// 幂等：同一证书再次完成同一计划，返回原结果，不刷新完成时间。
322		// 返回的同样是独立副本：即使把它改成未完成或换掉证书编号，正式计划
323		// 仍保持完成、原证书仍算已用于该计划。
324		if p.Status == PlanStatusDone {
325			if p.CertificateNumber == certificateNumber {
326				return clonePlanPtr(p), true, nil
327			}
328			return nil, false, validationError(
329				"计划 %s 已用证书 %s 完成，已完成计划不能改用另一证书",
330				number, p.CertificateNumber)
331		}
332		if p.Status == PlanStatusCanceled {
333			return nil, false, validationError("计划 %s 已取消，取消的计划不能完成；需要继续安排请建立新计划", number)
334		}
335	
336		cert := l.findCertificate(certificateNumber)
337		if cert == nil {
338			return nil, false, fmt.Errorf("证书编号 %s：%w", certificateNumber, ErrNotFound)
339		}
340		if cert.InstrumentID != p.InstrumentID {
341			return nil, false, validationError(
342				"证书 %s 属于器具 %s，不能用于完成器具 %s 的计划 %s",
343				certificateNumber, cert.InstrumentID, p.InstrumentID, number)
344		}
345		// 计划建立的本机日期：CreatedAt 是 RFC3339，取其日历日期；与证书校准日期
346		// 按日历日期比较，校准日期不得早于该日期（等于可以）。
347		created, perr := time.Parse(time.RFC3339, p.CreatedAt)
348		if perr != nil {
349			return nil, false, fmt.Errorf("计划 %s 建立时间已损坏: %w", number, perr)
350		}
351		createdDay := created.Format(DateLayout)
352		if cert.CalDate < createdDay {
353			return nil, false, validationError(
354				"证书 %s 的校准日期 %s 早于计划 %s 的建立日期 %s，不能用于完成该计划",
355				certificateNumber, cert.CalDate, number, createdDay)
356		}
357		// 同一证书不能用于完成两项计划；以幂等方式再次完成本计划已在前面处理。
358		for i := range l.data.Plans {
359			other := &l.data.Plans[i]
360			if other.Number != number && other.Status == PlanStatusDone &&
361				other.CertificateNumber == certificateNumber {
362				return nil, false, validationError(
363					"证书 %s 已用于完成计划 %s，不能再用于完成其他计划",
364					certificateNumber, other.Number)
365			}
366		}
367	
368		completedAt := l.now().Format(time.RFC3339)
369		// 在整份计划切片的独立副本上暂存完成：只有原子替换台账文件成功后才提交。
370		// 写盘失败时恢复原切片（计划仍为未完成、完成时间与关联证书编号为空），
371		// 保证同一台账对象随后看到的计划状态、待办与证书占用都与完成前一致，
372		// 再次提交不会被当成“此前已完成”，失败信息也不会被之后的写盘顺带写入。
373		original := l.data.Plans
374		staged := make([]Plan, len(original))
375		copy(staged, original)
376		for i := range staged {
377			if staged[i].Number != number {
378				continue
379			}
380			staged[i].Status = PlanStatusDone
381			staged[i].CompletedAt = completedAt
382			staged[i].CertificateNumber = certificateNumber
383		}
384		l.data.Plans = staged
385		if err := l.save(); err != nil {
386			l.data.Plans = original
387			return nil, false, err
388		}
389		return clonePlanPtr(l.findPlan(number)), false, nil
390	}
391	
392	// TodoItem 是待办查询中的一项计划及其按本机日期重新判断的标记。
393	type TodoItem struct {
394		PlanNumber     string `json:"plan_number"`
395		InstrumentID   string `json:"instrument_id"`
396		InstrumentName string `json:"instrument_name"`
397		Status         Status `json:"status"`
398		PlannedDate    string `json:"planned_date"`
399		Note           string `json:"note"`
400		Marker         string `json:"marker"`
401	}
402	
403	// planMarker 按计划日期相对今天给出标记：今天“今天需校准”，已过“逾期”，
404	// 未来“未到计划日”。
405	func planMarker(plannedDate, todayText string) string {
406		switch {
407		case plannedDate < todayText:
408			return TodoOverdue
409		case plannedDate == todayText:
410			return TodoToday
411		default:
412			return TodoFuture
413		}
414	}
415	
416	// Todos 列出未结束的计划作为待办。instrumentID 为空时列出全部器具的待办，
417	// 否则只列该器具（器具不存在时报 ErrNotFound）。结果按计划日期从早到晚、
418	// 同日按器具编号排列。查询不产生任何使用记录或写盘。
419	func (l *Ledger) Todos(instrumentID string) ([]TodoItem, error) {
420		id := strings.TrimSpace(instrumentID)
421		if id != "" && l.findInstrument(id) == nil {
422			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
423		}
424		todayText := l.now().Format(DateLayout)
425		items := []TodoItem{}
426		for _, p := range l.data.Plans {
427			if !p.Open() {
428				continue
429			}
430			if id != "" && p.InstrumentID != id {
431				continue
432			}
433			inst := l.findInstrument(p.InstrumentID)
434			if inst == nil {
435				continue
436			}
437			items = append(items, TodoItem{
438				PlanNumber:     p.Number,
439				InstrumentID:   inst.ID,
440				InstrumentName: inst.Name,
441				Status:         inst.Status,
442				PlannedDate:    p.PlannedDate,
443				Note:           p.Note,
444				Marker:         planMarker(p.PlannedDate, todayText),
445			})
446		}
447		sort.Slice(items, func(i, j int) bool {
448			if items[i].PlannedDate != items[j].PlannedDate {
449				return items[i].PlannedDate < items[j].PlannedDate
450			}
451			return items[i].InstrumentID < items[j].InstrumentID
452		})
453		return items, nil
454	}
455	
456	// PlanView 是计划的完整视图，供按器具核对时展示当前与已结束计划、
457	// 改期记录和关联证书编号。
458	type PlanView struct {
459		Plan
460		Marker string `json:"marker"`
461	}
462	
463	// plansOf 返回某器具的全部计划（含已结束），按建立先后排列。
464	// 返回的是深拷贝（含改期历史）：调用方整理按器具查询或核对结果中的
465	// 计划与改期记录，不会回写台账，也不会影响此前或之后分别取得的其他结果。
466	func (l *Ledger) plansOf(id string) []Plan {
467		var out []Plan
468		for _, p := range l.data.Plans {
469			if p.InstrumentID == id {
470				out = append(out, clonePlan(p))
471			}
472		}
473		sort.SliceStable(out, func(i, j int) bool { return out[i].CreatedAt < out[j].CreatedAt })
474		return out
475	}
476	
477	// planViews 构造器具核对用的计划视图；标记仅对未结束计划有意义。
478	func (l *Ledger) planViews(id string, today time.Time) []PlanView {
479		todayText := today.Format(DateLayout)
480		plans := l.plansOf(id)
481		out := make([]PlanView, 0, len(plans))
482		for _, p := range plans {
483			v := PlanView{Plan: p}
484			if p.Open() {
485				v.Marker = planMarker(p.PlannedDate, todayText)
486			}
487			out = append(out, v)
488		}
489		return out
490	}
491	
492	// Plans 返回某器具的全部计划（含已结束），按建立先后排列；
493	// 器具不存在时报 ErrNotFound。返回的计划（含改期历史）都是独立展示副本：
494	// 调用方调换顺序、删改或追加记录或改动任何字段，只影响自己手中的结果，
495	// 不回写台账，也不影响此前或之后分别取得的操作结果与核对结果。查询不写盘。
496	func (l *Ledger) Plans(instrumentID string) ([]PlanView, error) {
497		id := strings.TrimSpace(instrumentID)
498		inst := l.findInstrument(id)
499		if inst == nil {
500			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
501		}
502		return l.planViews(id, l.now()), nil
503	}
504

file.content:
package calibrate

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

// 计划状态：进行中的计划可改期、取消或完成；已完成与已取消均为终态，
// 不能再改期、取消或重新开启。
const (
	PlanStatusOpen     = "未完成"
	PlanStatusDone     = "已完成"
	PlanStatusCanceled = "已取消"
)

// 待办相对本机今天的标记。
const (
	TodoToday   = "今天需校准"
	TodoOverdue = "逾期"
	TodoFuture  = "未到计划日"
)

// PlanChange 记录一次改期：保留修改前后的日期、操作时间和原因。
type PlanChange struct {
	From      string `json:"from"`
	To        string `json:"to"`
	ChangedAt string `json:"changed_at"`
	Reason    string `json:"reason"`
}

// Plan 是一项校准计划。编号在全台账唯一，即使计划已结束编号也不再复用。
type Plan struct {
	Number       string `json:"number"`
	InstrumentID string `json:"instrument_id"`
	// PlannedDate 是当前计划日期；OriginalDate 保留建立时的计划日期。
	PlannedDate  string       `json:"planned_date"`
	OriginalDate string       `json:"original_date"`
	Note         string       `json:"note"`
	CreatedAt    string       `json:"created_at"`
	Changes      []PlanChange `json:"changes,omitempty"`
	Status       string       `json:"status"`
	// 取消时保留原计划日期、取消时间和原因。
	CanceledAt   string `json:"canceled_at,omitempty"`
	CancelReason string `json:"cancel_reason,omitempty"`
	// 完成时保存完成时间和所用证书编号。
	CompletedAt       string `json:"completed_at,omitempty"`
	CertificateNumber string `json:"certificate_number,omitempty"`
}

// Open 报告计划是否尚未结束（未完成、未取消）。
func (p Plan) Open() bool { return p.Status == PlanStatusOpen }

// PlanInput 是建立校准计划的输入。
type PlanInput struct {
	Number       string
	InstrumentID string
	Date         string
	Note         string
}

func (l *Ledger) findPlan(number string) *Plan {
	for i := range l.data.Plans {
		if l.data.Plans[i].Number == number {
			return &l.data.Plans[i]
		}
	}
	return nil
}

// cloneChanges 返回改期历史切片的独立副本，使对外返回的计划与台账内部
// 存储不共享底层数组：调用方调换顺序、删改或追加展示用记录，不会改写
// 正式的改期历史。nil 保持 nil，以维持“没有改期历史”的既有表现。
func cloneChanges(in []PlanChange) []PlanChange {
	if in == nil {
		return nil
	}
	return append([]PlanChange(nil), in...)
}

// clonePlan 返回计划的独立深拷贝，连同改期历史一起复制。
func clonePlan(p Plan) Plan {
	p.Changes = cloneChanges(p.Changes)
	return p
}

// clonePlanPtr 返回台账内计划的独立深拷贝；找不到时返回 nil。
// 各计划操作返回的计划只是已保存内容的展示副本：调用方为了显示而改动
// 编号、日期、状态、关联证书或改期记录，都不能成为绕过计划操作直接改写
// 台账的途径，也不会在此后正常写盘时被带入台账文件。
func clonePlanPtr(p *Plan) *Plan {
	if p == nil {
		return nil
	}
	cp := clonePlan(*p)
	return &cp
}

// validatePlanDate 解析 YYYY-MM-DD 真实日期，且不得早于本机今天。
func (l *Ledger) validatePlanDate(raw, field string) (string, error) {
	_, text, err := parseFiniteDate(raw, field)
	if err != nil {
		return "", err
	}
	todayText := l.now().Format(DateLayout)
	if text < todayText {
		return "", validationError("%s %s 不能早于本机今天 %s", field, text, todayText)
	}
	return text, nil
}

// CreatePlan 为已登记器具建立一项校准计划。计划编号全台账唯一（即使对应
// 已结束计划也不能复用），计划日期须真实存在且不早于本机今天，说明非空；
// 每件器具最多有一项未完成、未取消的计划。任一条件不满足都明确拒绝，
// 不新增或改动任何记录。
//
// 返回的计划只是已保存内容的展示副本，与台账内存储不共享内存：调用方为
// 显示而改动编号、日期、状态或关联证书，不占用或释放正式计划编号，不影响
// 每件器具最多一项未结束计划的判断，也不会在此后正常写盘时被带入台账文件；
// 重新查询同一台账得到的仍是最后成功保存的计划。
func (l *Ledger) CreatePlan(in PlanInput) (*Plan, error) {
	number, err := cleanText(in.Number)
	if err != nil {
		return nil, fmt.Errorf("计划编号无效：%w", err)
	}
	instID, err := cleanText(in.InstrumentID)
	if err != nil {
		return nil, fmt.Errorf("器具编号无效：%w", err)
	}
	note, err := cleanText(in.Note)
	if err != nil {
		return nil, fmt.Errorf("计划说明无效：%w", err)
	}
	if l.findInstrument(instID) == nil {
		return nil, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
	}
	dateText, err := l.validatePlanDate(in.Date, "计划日期")
	if err != nil {
		return nil, err
	}
	if l.findPlan(number) != nil {
		return nil, validationError("计划编号 %s 已存在，编号必须全台账唯一且不能复用", number)
	}
	for i := range l.data.Plans {
		p := &l.data.Plans[i]
		if p.InstrumentID == instID && p.Open() {
			return nil, validationError(
				"器具 %s 已有未结束的计划 %s（计划日期 %s），每件器具最多一项未结束计划",
				instID, p.Number, p.PlannedDate)
		}
	}
	p := Plan{
		Number:       number,
		InstrumentID: instID,
		PlannedDate:  dateText,
		OriginalDate: dateText,
		Note:         note,
		CreatedAt:    l.now().Format(time.RFC3339),
		Status:       PlanStatusOpen,
	}
	l.data.Plans = append(l.data.Plans, p)
	if err := l.save(); err != nil {
		return nil, err
	}
	return clonePlanPtr(l.findPlan(number)), nil
}

// requireOpenPlan 找到计划并确认其尚未结束；已结束计划返回明确的校验错误。
func (l *Ledger) requireOpenPlan(number string) (*Plan, error) {
	p := l.findPlan(number)
	if p == nil {
		return nil, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
	}
	if !p.Open() {
		return nil, validationError("计划 %s %s，已结束的计划不能再改期、取消或重新开启",
			number, p.Status)
	}
	return p, nil
}

// ReschedulePlan 改期一项未结束的计划。原因必须非空，新日期必须真实存在且
// 不早于操作当天；每次改期保留修改前后的日期、操作时间和原因。
// 找不到计划或计划已结束时拒绝且不改动记录。
//
// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
// 台账（含同一对象随后的核对、计划查询与待办）与改期前完全一致——当前计划
// 日期不改变，失败申请的原因和时间既不进入改期历史、不改变待办标记，也不会
// 在此后其他成功操作写盘时被顺带写入；恢复可写后重新提交才按当时时间生效，
// 且只新增一条从最后成功保存的日期到新日期的记录。
//
// 返回的计划（含改期历史）是已保存内容的独立展示副本：调用方改动其中的
// 当前日期、状态或任意一条改期记录的原因、前后日期、操作时间，调换、删去
// 或追加列表记录，都只影响自己手中的那一份，不改写正式计划，也不影响
// 此前分别取得的操作结果、计划查询结果和核对结果。
func (l *Ledger) ReschedulePlan(number, newDate, reason string) (*Plan, error) {
	number, err := cleanText(number)
	if err != nil {
		return nil, fmt.Errorf("计划编号无效：%w", err)
	}
	reason, err = cleanText(reason)
	if err != nil {
		return nil, fmt.Errorf("改期原因无效：%w", err)
	}
	dateText, err := l.validatePlanDate(newDate, "新计划日期")
	if err != nil {
		return nil, err
	}
	p, err := l.requireOpenPlan(number)
	if err != nil {
		return nil, err
	}
	// 即使新日期与当前日期相同也照常记录：保留修改前后的日期、操作时间和原因。
	change := PlanChange{
		From:      p.PlannedDate,
		To:        dateText,
		ChangedAt: l.now().Format(time.RFC3339),
		Reason:    reason,
	}
	// 在整份计划切片的独立副本上暂存改期：只有原子替换台账文件成功后才提交。
	// 写盘失败时恢复原切片（含原计划日期与改期历史），保证同一台账对象随后看到的
	// 计划日期、改期历史与待办标记都与改期前一致，且不会被之后的写盘顺带写入。
	original := l.data.Plans
	staged := make([]Plan, len(original))
	copy(staged, original)
	for i := range staged {
		if staged[i].Number != number {
			continue
		}
		staged[i].Changes = append(append([]PlanChange(nil), staged[i].Changes...), change)
		staged[i].PlannedDate = dateText
	}
	l.data.Plans = staged
	if err := l.save(); err != nil {
		l.data.Plans = original
		return nil, err
	}
	return clonePlanPtr(l.findPlan(number)), nil
}

// CancelPlan 取消一项未结束的计划，原因必须非空。取消后保留原计划、取消时间
// 和原因，不再列入待办，也不能重新开启。找不到计划或计划已结束时拒绝。
//
// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
// 台账（含同一对象随后的计划查询、按器具核对与待办）与取消前完全一致——
// 计划仍为未完成并继续列入待办，取消时间和原因不留下本次申请的内容，也不会
// 在此后其他成功操作写盘时被顺带写入；文件仍不可写时再次提交仍报保存错误
// （不会被当成“已结束”拒绝），恢复可写后无需重新打开台账，重新提交才真正
// 取消，取消时间和原因取本次成功提交而非失败那次。
//
// 返回的取消结果是独立展示副本：调用方把状态改回未完成或清空取消信息，
// 只影响自己那一份，正式计划仍保持已取消且不再列入待办。
func (l *Ledger) CancelPlan(number, reason string) (*Plan, error) {
	number, err := cleanText(number)
	if err != nil {
		return nil, fmt.Errorf("计划编号无效：%w", err)
	}
	reason, err = cleanText(reason)
	if err != nil {
		return nil, fmt.Errorf("取消原因无效：%w", err)
	}
	if _, err := l.requireOpenPlan(number); err != nil {
		return nil, err
	}
	canceledAt := l.now().Format(time.RFC3339)
	// 在整份计划切片的独立副本上暂存取消：只有原子替换台账文件成功后才提交。
	// 写盘失败时恢复原切片（计划仍为未完成、取消时间与原因为空），保证同一
	// 台账对象随后看到的计划状态、待办与核对都与取消前一致，再次提交不会被
	// 当成“已结束”，失败信息也不会被之后的写盘顺带写入。
	original := l.data.Plans
	staged := make([]Plan, len(original))
	copy(staged, original)
	for i := range staged {
		if staged[i].Number != number {
			continue
		}
		staged[i].Status = PlanStatusCanceled
		staged[i].CanceledAt = canceledAt
		staged[i].CancelReason = reason
	}
	l.data.Plans = staged
	if err := l.save(); err != nil {
		l.data.Plans = original
		return nil, err
	}
	return clonePlanPtr(l.findPlan(number)), nil
}

// CompletePlan 用一张台账中已有的证书完成计划。证书必须属于该器具，校准日期
// 不得早于计划最初建立的本机日期，且未被用于完成其他计划。符合条件后保存
// 完成时间和证书编号；超差证书同样表示校准工作已完成。
//
// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
// 台账（含同一对象随后的计划查询、按器具核对与待办）与完成前完全一致——
// 计划仍为未完成并继续列入待办，完成时间与关联证书编号保持操作前的值，
// 计划日期、已有改期记录和待办日期标记都不改变，该证书也不会被算作已用于
// 完成计划（既不会被随后的提交当成“此前已完成”跳过保存，也不会被其他成功
// 写盘顺带写入文件）；恢复可写后无需重新打开台账，重新提交才真正完成，
// 完成时间取本次成功操作而非失败时刻。
//
// 再次用同一证书完成同一已保存为完成的计划返回原结果，不增加记录或刷新
// 完成时间；已完成计划改用另一证书、证书不存在或不符合条件、完成已取消
// 计划均拒绝。
//
// 返回的完成结果（含再次完成返回的原结果）是独立展示副本：调用方把它改成
// 未完成或换掉证书编号，正式计划仍保持完成，原证书仍算已用于该计划，不能
// 因此拿去完成另一项计划，完成时间也不会被刷新。
func (l *Ledger) CompletePlan(number, certificateNumber string) (*Plan, bool, error) {
	number, err := cleanText(number)
	if err != nil {
		return nil, false, fmt.Errorf("计划编号无效：%w", err)
	}
	certificateNumber, err = cleanText(certificateNumber)
	if err != nil {
		return nil, false, fmt.Errorf("证书编号无效：%w", err)
	}
	p := l.findPlan(number)
	if p == nil {
		return nil, false, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
	}
	// 幂等：同一证书再次完成同一计划，返回原结果，不刷新完成时间。
	// 返回的同样是独立副本：即使把它改成未完成或换掉证书编号，正式计划
	// 仍保持完成、原证书仍算已用于该计划。
	if p.Status == PlanStatusDone {
		if p.CertificateNumber == certificateNumber {
			return clonePlanPtr(p), true, nil
		}
		return nil, false, validationError(
			"计划 %s 已用证书 %s 完成，已完成计划不能改用另一证书",
			number, p.CertificateNumber)
	}
	if p.Status == PlanStatusCanceled {
		return nil, false, validationError("计划 %s 已取消，取消的计划不能完成；需要继续安排请建立新计划", number)
	}

	cert := l.findCertificate(certificateNumber)
	if cert == nil {
		return nil, false, fmt.Errorf("证书编号 %s：%w", certificateNumber, ErrNotFound)
	}
	if cert.InstrumentID != p.InstrumentID {
		return nil, false, validationError(
			"证书 %s 属于器具 %s，不能用于完成器具 %s 的计划 %s",
			certificateNumber, cert.InstrumentID, p.InstrumentID, number)
	}
	// 计划建立的本机日期：CreatedAt 是 RFC3339，取其日历日期；与证书校准日期
	// 按日历日期比较，校准日期不得早于该日期（等于可以）。
	created, perr := time.Parse(time.RFC3339, p.CreatedAt)
	if perr != nil {
		return nil, false, fmt.Errorf("计划 %s 建立时间已损坏: %w", number, perr)
	}
	createdDay := created.Format(DateLayout)
	if cert.CalDate < createdDay {
		return nil, false, validationError(
			"证书 %s 的校准日期 %s 早于计划 %s 的建立日期 %s，不能用于完成该计划",
			certificateNumber, cert.CalDate, number, createdDay)
	}
	// 同一证书不能用于完成两项计划；以幂等方式再次完成本计划已在前面处理。
	for i := range l.data.Plans {
		other := &l.data.Plans[i]
		if other.Number != number && other.Status == PlanStatusDone &&
			other.CertificateNumber == certificateNumber {
			return nil, false, validationError(
				"证书 %s 已用于完成计划 %s，不能再用于完成其他计划",
				certificateNumber, other.Number)
		}
	}

	completedAt := l.now().Format(time.RFC3339)
	// 在整份计划切片的独立副本上暂存完成：只有原子替换台账文件成功后才提交。
	// 写盘失败时恢复原切片（计划仍为未完成、完成时间与关联证书编号为空），
	// 保证同一台账对象随后看到的计划状态、待办与证书占用都与完成前一致，
	// 再次提交不会被当成“此前已完成”，失败信息也不会被之后的写盘顺带写入。
	original := l.data.Plans
	staged := make([]Plan, len(original))
	copy(staged, original)
	for i := range staged {
		if staged[i].Number != number {
			continue
		}
		staged[i].Status = PlanStatusDone
		staged[i].CompletedAt = completedAt
		staged[i].CertificateNumber = certificateNumber
	}
	l.data.Plans = staged
	if err := l.save(); err != nil {
		l.data.Plans = original
		return nil, false, err
	}
	return clonePlanPtr(l.findPlan(number)), false, nil
}

// TodoItem 是待办查询中的一项计划及其按本机日期重新判断的标记。
type TodoItem struct {
	PlanNumber     string `json:"plan_number"`
	InstrumentID   string `json:"instrument_id"`
	InstrumentName string `json:"instrument_name"`
	Status         Status `json:"status"`
	PlannedDate    string `json:"planned_date"`
	Note           string `json:"note"`
	Marker         string `json:"marker"`
}

// planMarker 按计划日期相对今天给出标记：今天“今天需校准”，已过“逾期”，
// 未来“未到计划日”。
func planMarker(plannedDate, todayText string) string {
	switch {
	case plannedDate < todayText:
		return TodoOverdue
	case plannedDate == todayText:
		return TodoToday
	default:
		return TodoFuture
	}
}

// Todos 列出未结束的计划作为待办。instrumentID 为空时列出全部器具的待办，
// 否则只列该器具（器具不存在时报 ErrNotFound）。结果按计划日期从早到晚、
// 同日按器具编号排列。查询不产生任何使用记录或写盘。
func (l *Ledger) Todos(instrumentID string) ([]TodoItem, error) {
	id := strings.TrimSpace(instrumentID)
	if id != "" && l.findInstrument(id) == nil {
		return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
	}
	todayText := l.now().Format(DateLayout)
	items := []TodoItem{}
	for _, p := range l.data.Plans {
		if !p.Open() {
			continue
		}
		if id != "" && p.InstrumentID != id {
			continue
		}
		inst := l.findInstrument(p.InstrumentID)
		if inst == nil {
			continue
		}
		items = append(items, TodoItem{
			PlanNumber:     p.Number,
			InstrumentID:   inst.ID,
			InstrumentName: inst.Name,
			Status:         inst.Status,
			PlannedDate:    p.PlannedDate,
			Note:           p.Note,
			Marker:         planMarker(p.PlannedDate, todayText),
		})
	}
	sort.Slice(items, func(i, j int) bool {
		if items[i].PlannedDate != items[j].PlannedDate {
			return items[i].PlannedDate < items[j].PlannedDate
		}
		return items[i].InstrumentID < items[j].InstrumentID
	})
	return items, nil
}

// PlanView 是计划的完整视图，供按器具核对时展示当前与已结束计划、
// 改期记录和关联证书编号。
type PlanView struct {
	Plan
	Marker string `json:"marker"`
}

// plansOf 返回某器具的全部计划（含已结束），按建立先后排列。
// 返回的是深拷贝（含改期历史）：调用方整理按器具查询或核对结果中的
// 计划与改期记录，不会回写台账，也不会影响此前或之后分别取得的其他结果。
func (l *Ledger) plansOf(id string) []Plan {
	var out []Plan
	for _, p := range l.data.Plans {
		if p.InstrumentID == id {
			out = append(out, clonePlan(p))
		}
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].CreatedAt < out[j].CreatedAt })
	return out
}

// planViews 构造器具核对用的计划视图；标记仅对未结束计划有意义。
func (l *Ledger) planViews(id string, today time.Time) []PlanView {
	todayText := today.Format(DateLayout)
	plans := l.plansOf(id)
	out := make([]PlanView, 0, len(plans))
	for _, p := range plans {
		v := PlanView{Plan: p}
		if p.Open() {
			v.Marker = planMarker(p.PlannedDate, todayText)
		}
		out = append(out, v)
	}
	return out
}

// Plans 返回某器具的全部计划（含已结束），按建立先后排列；
// 器具不存在时报 ErrNotFound。返回的计划（含改期历史）都是独立展示副本：
// 调用方调换顺序、删改或追加记录或改动任何字段，只影响自己手中的结果，
// 不回写台账，也不影响此前或之后分别取得的操作结果与核对结果。查询不写盘。
func (l *Ledger) Plans(instrumentID string) ([]PlanView, error) {
	id := strings.TrimSpace(instrumentID)
	inst := l.findInstrument(id)
	if inst == nil {
		return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
	}
	return l.planViews(id, l.now()), nil
}

