115			view.Plans[0].CanceledAt != "" || view.Plans[0].CancelReason != "" {
116			t.Fatalf("核对应展示尚未取消的计划：%+v", view.Plans)
117		}
118		raw, err := os.ReadFile(target)
119		if err != nil {
120			t.Fatalf("读取台账文件: %v", err)
121		}
122		if strings.Contains(string(raw), "暂停送检") || strings.Contains(string(raw), "已取消") {
123			t.Fatalf("失败取消已存在于台账文件：\n%s", raw)
124		}
125	
126		// 恢复目录可写：先做一次无关的正常操作（器具停用）并保存成功，
127		// 失败的取消内容不能被顺带写入。
128		if err := os.Chmod(sub, 0o755); err != nil {
129			t.Fatal(err)
130		}
131		if st := runArgs(t, "status", "-f", target, "--id", "M-1", "--status", "停用"); st.code != 0 {
132			t.Fatalf("恢复后正常操作应能保存：%s", st.stderr)
133		}
134		raw, err = os.ReadFile(target)
135		if err != nil {
136			t.Fatalf("读取台账文件: %v", err)
137		}
138		if strings.Contains(string(raw), "暂停送检") || strings.Contains(string(raw), "已取消") {
139			t.Fatalf("失败取消被随后成功的写盘顺带写入文件：\n%s", raw)
140		}
141	
142		// 停用器具的未结束计划仍允许取消：重新提交才成功，核对展示取消时间和原因，
143		// 待办不再包含该计划；已取消计划不能再次取消或改期。
144		ok := runArgs(t, cancelArgs(target, "P-1", "实验室长期停用")...)
145		if ok.code != 0 || !strings.Contains(ok.stdout, "取消") ||
146			!strings.Contains(ok.stdout, "不再列入待办") {
147			t.Fatalf("恢复后取消应成功：code=%d stdout=%q stderr=%s", ok.code, ok.stdout, ok.stderr)
148		}
149		after := runArgs(t, "review", "--id", "M-1", "-f", target, "--json")
150		var final struct {
151			Plans []struct {
152				Status       string `json:"status"`
153				CanceledAt   string `json:"canceled_at"`
154				CancelReason string `json:"cancel_reason"`
155			} `json:"plans"`
156		}
157		if err := json.Unmarshal([]byte(after.stdout), &final); err != nil {
158			t.Fatalf("解析 review JSON 失败: %v\n%s", err, after.stdout)
159		}
160		if len(final.Plans) != 1 || final.Plans[0].Status != "已取消" ||
161			final.Plans[0].CanceledAt == "" || final.Plans[0].CancelReason != "实验室长期停用" {
162			t.Fatalf("核对应展示本次成功的取消时间和原因：%+v", final.Plans)
163		}
164		tv2 := runArgs(t, "todos", "-f", target, "--json")
165		if strings.Contains(tv2.stdout, "P-1") {
166			t.Fatalf("成功取消后待办不应再包含该计划：%s", tv2.stdout)
167		}
168		if again := runArgs(t, cancelArgs(target, "P-1", "再次取消")...); again.code != 1 {
169			t.Fatalf("已取消计划再次取消应业务拒绝退出 1，得到 %d", again.code)
170		}
