113	// CreatePlan 为已登记器具建立一项校准计划。计划编号全台账唯一（即使对应
114	// 已结束计划也不能复用），计划日期须真实存在且不早于本机今天，说明非空；
115	// 每件器具最多有一项未完成、未取消的计划。任一条件不满足都明确拒绝，
116	// 不新增或改动任何记录。
117	//
118	// 返回的计划只是已保存内容的展示副本，与台账内存储不共享内存：调用方为
119	// 显示而改动编号、日期、状态或关联证书，不占用或释放正式计划编号，不影响
120	// 每件器具最多一项未结束计划的判断，也不会在此后正常写盘时被带入台账文件；
121	// 重新查询同一台账得到的仍是最后成功保存的计划。
122	func (l *Ledger) CreatePlan(in PlanInput) (*Plan, error) {
123		number, err := cleanText(in.Number)
124		if err != nil {
125			return nil, fmt.Errorf("计划编号无效：%w", err)
126		}
127		instID, err := cleanText(in.InstrumentID)
128		if err != nil {
129			return nil, fmt.Errorf("器具编号无效：%w", err)
130		}
131		note, err := cleanText(in.Note)
132		if err != nil {
133			return nil, fmt.Errorf("计划说明无效：%w", err)
134		}
135		if l.findInstrument(instID) == nil {
136			return nil, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
137		}
138		dateText, err := l.validatePlanDate(in.Date, "计划日期")
139		if err != nil {
140			return nil, err
141		}
142		if l.findPlan(number) != nil {
143			return nil, validationError("计划编号 %s 已存在，编号必须全台账唯一且不能复用", number)
144		}
145		for i := range l.data.Plans {
146			p := &l.data.Plans[i]
147			if p.InstrumentID == instID && p.Open() {
148				return nil, validationError(
149					"器具 %s 已有未结束的计划 %s（计划日期 %s），每件器具最多一项未结束计划",
150					instID, p.Number, p.PlannedDate)
151			}
152		}
153	// 业务校验全部通过后才写盘：只有真正保存成功，这项计划才算建立。若台账文件
154	// 无法写入或替换，明确返回保存错误，台账（含同一对象随后的计划查询、待办与
155	// 按器具核对）与建立前完全一致——失败的计划不占用编号，也不占用该器具唯一的
156	// 未结束计划名额，不会在此后其他成功操作写盘时被顺带写入；文件仍不可写时再次
157	// 提交相同编号与内容仍报保存错误（不会被当成编号重复或器具已有未结束计划而
158	// 业务拒绝）；恢复可写后无需重新打开台账，重新提交才作为新计划建立，
159	// 建立时间取本次成功申请的时间。
160		p := Plan{
161			Number:       number,
162			InstrumentID: instID,
163			PlannedDate:  dateText,
164			OriginalDate: dateText,
165			Note:         note,
166			CreatedAt:    l.now().Format(time.RFC3339),
167			Status:       PlanStatusOpen,
