package main

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// planCreateArgs 构造一条指定日期与说明的新建计划命令。
func planCreateArgs(path, instrument, number, date, note string) []string {
	return []string{"plan", "-f", path,
		"--instrument", instrument, "--number", number,
		"--date", date, "--note", note}
}

// TestPlanSaveFailureIsFileErrorAndRecoverable 验证命令行新建校准计划在台账文件
// 无法写入时按文件读写错误报告、退出码 2（普通输出与 --json 一致）、不输出已建立成功；
// 失败的计划不占用编号、不占用该器具唯一的未结束计划名额，待办与核对都看不到它。
// 文件仍不可写时再次提交相同编号内容仍退出 2，而不是被当成编号重复或器具已有计划（退出 1）。
// 恢复可写后重新提交才建立并出现在待办与核对中；此前保存的计划及其改期、取消、完成信息
// 保持原样；未通过业务检查的申请仍按原方式拒绝，不能因台账不可写被混成保存失败。
func TestPlanSaveFailureIsFileErrorAndRecoverable(t *testing.T) {
	dir := chdirTemp(t)
	// 台账放在子目录里：把子目录改成只读即可挡住写临时文件与改名替换，
	// 已存在的台账文件本身仍可读，查询不受影响。
	sub := filepath.Join(dir, "只读目录")
	if err := os.Mkdir(sub, 0o755); err != nil {
		t.Fatal(err)
	}
	target := filepath.Join(sub, "ledger.json")
	if r := runArgs(t, registerArgs(target, "M-1")...); r.code != 0 {
		t.Fatalf("登记器具失败 code=%d stderr=%s", r.code, r.stderr)
	}
	// 先成功建立一项计划 P-SAVED，作为“此前已保存的计划”：失败申请不得改动它，
	// 也不应让它在待办或核对中消失。
	if r := runArgs(t, planCreateArgs(target, "M-1", "P-SAVED", "2030-10-10", "已保存的计划")...); r.code != 0 {
		t.Fatalf("建立已保存计划失败 code=%d stderr=%s", r.code, r.stderr)
	}

	// 目录只读：save 无法创建临时文件；测试结束后恢复权限便于清理。
	if err := os.Chmod(sub, 0o555); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.Chmod(sub, 0o755) })

	// 合法新建写盘失败：退出码 2，按文件读写错误报告，不显示“已为器具…建立”，
	// 错误信息指出台账文件，也不能说成编号重复或器具已有计划。
	failArgs := planCreateArgs(target, "M-2-no", "P-NEW", "2030-10-20", "失败的新计划")
	// M-1 已有未结束计划 P-SAVED，新计划登记在第二件器具 M-2 上以构造合法申请。
	if r := runArgs(t, registerArgs(filepath.Join(dir, "其他.json"), "M-2")...); r.code != 0 {
		t.Fatalf("准备第二份台账不应失败：%s", r.stderr)
	}
	_ = failArgs
	// 改用 M-1 会被业务规则拒绝（已有未结束计划），因此合法失败申请针对 M-2：
	// 在只读目录下无法登记 M-2，故改为在同一台账用未来日期为 M-1 申请新编号仍会先撞名额；
	// 这里直接用新器具在主台账中预先登记不可行（目录只读），因此合法失败申请通过
	// 另一份可写台账无法模拟——改为：先取消 P-SAVED 再新建同样受目录只读挡住取消。
	// 采用与其余写失败测试一致的做法：合法申请的业务条件在只读前已具备——
	// M-1 的名额在下面恢复段处理，本段先用 M-2 已在目标台账登记的事实不成立，
	// 故改为把第二件器具直接登记进目标台账（在目录只读之前完成）。
	// （上面的 Other.json 登记仅为占位说明，不影响目标台账。）

	// 在目录只读之前把 M-2 登记进目标台账。
	if err := os.Chmod(sub, 0o755); err != nil {
