		t.Fatalf("登记第二件器具失败 code=%d stderr=%s", r.code, r.stderr)
	}
	if err := os.Chmod(sub, 0o555); err != nil {
		t.Fatal(err)
	}
	legalFail := planCreateArgs(target, "M-2", "P-NEW", "2030-10-20", "失败的新计划")
	r := runArgs(t, legalFail...)
	if r.code != 2 {
