	if strings.Contains(string(raw), "P-NEW") || strings.Contains(string(raw), "失败的新计划") {
		t.Fatalf("失败计划被随后成功的写盘顺带写入文件：\n%s", raw)
	}

	// 无需重新打开台账：重新提交合法申请才成功建立（停用器具的计划名额同样不受限制），
