		t.Fatalf("解析 todos JSON 失败: %v\n%s", err, tv4.stdout)
	}
	got := map[string]bool{}
	for _, it := range allTodos.Todos {
		got[it.PlanNumber] = true
	}
	if !got["P-SAVED"] || !got["P-NEW"] || len(allTodos.Todos) != 2 {
		t.Fatalf("待办应同时包含此前保存的 P-SAVED 与新建的 P-NEW：%+v", allTodos.Todos)
	}
}

